// Base64
#include "base64/base64.hpp"


using namespace galimatron;
using namespace galimatron::translator::parser;

namespace
{

void parse_string_on_production(const content_t& content)
{
    auto state = state_t(content);
    state.do_production_parse();
}

struct parse_file_production_t
{
    path_t subpath;
    path_t filename;
};
void parse_file_on_production(const parse_file_production_t& args)
{
    static const path_t prefix_path = path_to_galimatron_test_data / "translator_library/parser";

    print_leaf_exception([&]
        {
            auto path = prefix_path / args.subpath / args.filename;
            path.replace_extension("gal");
            auto state = state_t(*executable::filesystem::physically::make_filesystem().read(path));
            state.do_production_parse();
        },
        false // is_print_to_cout = true for debug
    );
};

std::string parse_string_on_testing(const content_t& content)
{
    // a simple listener to get the result of walking the string
    //
    class listener_for_string_t : public g_parserBaseListener
    {
    public:
        listener_for_string_t(std::string& result)
            : result_(result)
        {}
    private:// g_parserBaseListener
        virtual void enterTestStringEntryPoint(g_parser::TestStringEntryPointContext * ctx) override
        {
            result_ = ctx->STRING()->getText();
        }
    private:
        std::string& result_;
    };

    auto state = state_t(content);
    state.do_test_string_parse();

    std::string result;
    auto listener = listener_for_string_t(result);

    translator::antlr_walk(&listener, state.tree());

    return result;
}

}// namespace

